// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { searchOwnersByLastName, sortOwnersByCity } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(138000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Search" }).click();
    const ownerRows = page.locator("#ownersTable table > tbody > tr");
    const ownerNames = ownerRows.locator("td.ownerFullName");

    await searchOwnersByLastName(page, "Davis");

    // The last-name filter narrows the list to the two Davis owners.
    await expect(ownerRows).toHaveCount(2);
    await expect(ownerNames.nth(0)).toHaveText("Betty Davis");
    await expect(ownerNames.nth(1)).toHaveText("Harold Davis");

    // Wait for the sort request to actually come back before asserting, otherwise
    // the assertions below run against the pre-click DOM and pass vacuously.
    const sortResponse = page.waitForResponse(response =>
        response.url().includes("/petclinic/api/owners")
        && new URL(response.url()).searchParams.get("sort") === "city"
    );
    await sortOwnersByCity(page);
    await sortResponse;
    await page.waitForLoadState("networkidle");

    // The search box still shows "Davis", so the list must stay filtered to the
    // two Davis owners -- re-sorting a filtered list must not widen it.
    await expect(page.getByRole("textbox", { name: "Last name" })).toHaveValue("Davis");
    await expect(ownerRows).toHaveCount(2);
    await expect(page.getByRole("link", { name: "George Franklin" })).toHaveCount(0);
});
